#!/usr/bin/env bash
# Run all GNN models on the A. thaliana within-species pathway holdout split.
#
# Split: splits_ath_pathway.pt  (generated by training/build_splits_ath.py)
# Ranking pool: A. thaliana proteins only (~5,289 with ESM-C, random P-H@50=0.95%)
#
# Run from repo root:
#   bash scripts/run_ath_baseline.sh
#
# Override python path:
#   PYTHON=/path/to/env/bin/python bash scripts/run_ath_baseline.sh

set -euo pipefail

PYTHON=${PYTHON:-python}
TRAIN=training/train_seeds.py
RESULTS=results/ath_baseline

COMMON="--seeds 42 0 1 2 3 --split_type ath_pathway --species_pool"

mkdir -p "$RESULTS"

echo "=============================="
echo " A. thaliana baseline — ath_pathway split, species pool"
echo "=============================="

for MODEL in HeteroSAGE HeteroGAT HGT; do
  echo ""
  echo "--- $MODEL ---"
  OUT="$RESULTS/${MODEL}_ath.json"
  if [[ -f "$OUT" ]]; then
    echo "  already exists, skipping."
  else
    $PYTHON $TRAIN $COMMON --model $MODEL --output "$OUT"
  fi
done

echo ""
echo "--- Dual encoder (L1) ---"
OUT="$RESULTS/dual_encoder_L1_ath.json"
if [[ -f "$OUT" ]]; then
  echo "  already exists, skipping."
else
  $PYTHON dual_encoder/train.py \
    --seeds 42 0 1 2 3 \
    --num_layers 1 \
    --split_type ath_pathway \
    --species_pool \
    --output "$OUT"
fi

echo ""
echo "=============================="
echo "All done. Results in $RESULTS/"
echo "=============================="
